/**
 * Platform Adapter Layer - Shared Type Definitions
 *
 * Defines the ContrapunkAdapter interface and all related types.
 * Components import from this module and never call Tauri or WASM directly.
 */

/** Represents a MIDI device (input or output). */
/** Maximum number of voices the app exposes. Must match MAX_VOICES in
 *  `src-tauri/src/state.rs`. */
export const MAX_VOICES = 8;

/** Per-voice output destination. Shape mirrors the Rust `VoiceOutputTarget`
 *  enum with `#[serde(tag = "kind", rename_all = "snake_case")]` — see
 *  `src-tauri/src/state.rs` and the `voice_output_target_json_shape_is_tagged`
 *  test in `src-tauri/src/commands/routing.rs`.
 *
 *    - `synth`     — internal synth only, skip external MIDI (DEFAULT)
 *    - `midi_port` — specific MIDI port only, skip the internal synth
 *    - `off`       — voice is silent
 */
export type VoiceOutputTarget =
	| { kind: 'synth' }
	| { kind: 'midi_port'; port: number }
	| { kind: 'off' };

export type PluginInputMode = 'midi' | 'audio';
export type PluginMidiOutputMode = 'full' | 'pass_through';

/** What lanes do with pending emissions when the player releases the
 *  NoteOn that seeded them (#11). Shape mirrors the Rust `HoldMode`
 *  enum's JSON serialization (`hold_mode_to_json` in
 *  `crates/contrapunk-companion/src/lane.rs`).
 *
 *    - `cancel`       — kill all pending derived from the released note.
 *    - `near_future`  — let pending within `tail_beats` of now fire;
 *                       cancel anything beyond.
 *    - `phrase_end`   — let pending within the current phrase
 *                       (anchor + beats_per_bar) fire; cancel beyond.
 *    - `forever`      — never cancel (pre-v1.2 behavior, preserves
 *                       canon-as-canon semantics).
 */
export type HoldMode =
	| { kind: 'cancel' }
	| { kind: 'near_future'; tail_beats: number }
	| { kind: 'phrase_end' }
	| { kind: 'forever' };

export interface MidiDevice {
	index: number;
	name: string;
}

/**
 * Browser MIDI permission state.
 *
 * `idle`        — never requested. Triggering a request requires a user gesture.
 * `granted`     — user accepted; device enumeration works.
 * `denied`      — user rejected. Recoverable only via browser settings; UI
 *                 should offer a "Try again" affordance.
 * `unsupported` — browser does not implement Web MIDI (Firefox historically).
 *                 Suggest the desktop app.
 */
export type MidiPermissionState = 'idle' | 'granted' | 'denied' | 'unsupported';

/** Snapshot of the harmony engine configuration. */
export interface EngineState {
	key: string;
	mode: string;
	modeNumber: number;
	scaleMode: string;
	octaveMode: string;
	octaveIntensity?: number;
	voiceLeadingEnabled: boolean;
	voiceLeadingStyle: string;
	interchangeEnabled: boolean;
	interchangeRange: number;
	voicePosition: number;
	voiceCount: number;
	autoKey: boolean;
	isRunning: boolean;
	counterpointSpecies: string;
	counterpointStrictness: string;
}

/** Real-time note state emitted during MIDI routing. */
export interface NoteState {
	inputNotes: number[];
	harmonyNotes: number[];
	borrowedNotes: number[];
	chordName: string;
	lastBorrowedFrom: string;
	currentKey: string;
	/** Companion-emitted notes attributed by originating lane. Harmony,
	 *  Canon, and Counterpoint are separate ownership sets so same-pitch
	 *  voices remain visible independently across all surfaces. */
	canonNotes?: number[];
	counterpointNotes?: number[];
}

/** Guitar DSP pipeline configuration sent to the backend. */
export interface GuitarConfig {
	latencyMs: number;
	gain: number;
	stringConfidence: number;
	bends: boolean;
	legato: boolean;
	slides: boolean;
	vibrato: boolean;
}

/** Preset metadata. */
export interface Preset {
	index: number;
	name: string;
	persona: string;
	genre: string;
	isBuiltin: boolean;
}

/** Snapshot of built-in synth parameters. */
export interface SynthState {
	enabled: boolean;
	waveform: number;
	attackMs: number;
	decayMs: number;
	sustain: number;
	releaseMs: number;
	cutoffHz: number;
	resonance: number;
	masterGain: number;
	/** Native performance-mixer base gains: input, harmony, canon, counterpoint. */
	mixGains?: number[];
}

/** Snapshot of built-in reverb parameters. */
export interface ReverbState {
	enabled: boolean;
	mix: number;
	roomSize: number;
	damping: number;
}

/** Canonical subdivision tags accepted by `setDelaySubdivision`. */
export type DelaySubdivision = '1/4' | '1/8d' | '1/8' | '1/8t' | '1/16' | '1/16t';

/** Snapshot of built-in delay parameters. */
export interface DelayState {
	enabled: boolean;
	mix: number;
	timeMs: number;
	feedback: number;
	/** When true, the delay tap length is derived from the transport
	 *  BPM and `subdivision`; otherwise `timeMs` is the free tap. */
	syncEnabled: boolean;
	subdivision: DelaySubdivision;
}

/** One block in the live audio chain. */
export interface ChainBlock {
	typeId: string;
	name: string;
}

/** Descriptor for a discovered CLAP plugin on disk. */
export interface ClapPluginDescriptor {
	id: string;
	name: string;
	vendor: string;
	version: string;
	path: string;
}

/** Returned from addClapPluginToChain — plugin is live, has a stable id for GUI control. */
export interface AddedPlugin {
	pluginId: number;
	name: string;
	path: string;
	hasGui: boolean;
}

/** Snapshot of transport / clock state. */
export interface TransportState {
	running: boolean;
	bpm: number;
	beatsPerBar: number;
	beatUnit: number;
	sampleRate: number;
	samplePos: number;
	beatPosition: number;
	bar: number;
	metronomeEnabled: boolean;
}

/**
 * Unified adapter interface for communicating with the Rust backend.
 *
 * Svelte components call these methods without knowing whether the
 * backend is reached via Tauri IPC (desktop) or WASM direct calls (browser).
 */
/** Feature gates exposed by an adapter so the UI can hide controls
 *  that would otherwise no-op silently on a given surface. Add a
 *  flag here when a feature ships on one surface before the others;
 *  remove it once parity catches up. */
export interface AdapterCapabilities {
	/** Whether the delay FX honors `setDelaySyncEnabled` /
	 *  `setDelaySubdivision`. False on WASM + plugin today — they
	 *  stub the setters because their audio paths don't read the
	 *  transport BPM. */
	delayTempoSync: boolean;
	/** Whether the audio chain topology (chain blocks) is editable
	 *  from this surface. False on WASM + plugin. */
	chainEditor: boolean;
	/** Whether the surface emits per-note state updates so the Piano
	 *  / Fretboard can light keys. True on Tauri + WASM + plugin
	 *  (plugin emits via editor on_frame). */
	noteUpdates: boolean;
	/** Whether this surface owns the transport (play/stop, BPM, time
	 *  signature). False in plugin mode — the DAW is the master
	 *  clock and exposes its own transport UI; ours would be a lie. */
	transportControl: boolean;
	/** Whether this surface routes MIDI itself, so device pickers and
	 *  the start/stop routing flow make sense. False in plugin mode
	 *  — the DAW handles MIDI routing. */
	midiDevicePicker: boolean;
	/** Whether the surface drives the built-in synth + FX (reverb,
	 *  delay). False in plugin mode — the DAW hosts audio and the
	 *  plugin emits MIDI only; the synth/FX racks would be inert. */
	audioFx: boolean;
	/** Whether the surface supports Companion lanes (canon +
	 *  counterpoint). False in plugin mode for v1.3.0 — plugin core
	 *  doesn't wire Companion yet (deferred to v1.4). The
	 *  CompanionPanel and master HoldMode toggle hide when false. */
	companionLanes: boolean;
	/** Whether the InputPanel renders the three-way source picker
	 *  (MIDI / Guitar Audio / Voice). False in plugin mode — the DAW
	 *  routes audio in and chooses the input bus itself, so the picker
	 *  would be inert. */
	inputSourcePicker: boolean;
	/** Whether the OutputPanel exposes per-voice MIDI port routing
	 *  pickers. False in plugin mode — the DAW assigns plugin output
	 *  channels and our per-voice picker would conflict. Tauri + WASM
	 *  both expose real MIDI out via the adapter's setVoiceOutput. */
	perVoicePortRouting: boolean;
	/** Whether plugin mode exposes a host-side MIDI output mode selector
	 *  (Full Contrapunk vs pass-through-only). False outside plugin mode. */
	pluginMidiOutputMode: boolean;
	/** Whether per-role Input/Harmony/Canon/Counterpoint synth gains are real. */
	roleMix: boolean;
	/** Whether the surface supports loading + saving the per-string
	 *  calibration profile to disk and applying it to the live guitar
	 *  pipeline. Tauri only for v1 — uses `app_data_dir()`. WASM /
	 *  plugin would need their own persistence story. */
	calibrationFlow: boolean;
}

/** Status returned from `getCalibrationStatus`. `sampleCounts[i]` is the
 *  total number of soft+strong calibration samples captured for string i
 *  (index 0 = Low E, 5 = High E). */
export interface CalibrationStatus {
	existsOnDisk: boolean;
	path: string;
	version: number;
	sampleCounts: number[];
}

export interface ContrapunkAdapter {
	/** Per-surface capability flags. Read in the UI to gate controls
	 *  that aren't wired on this adapter. */
	readonly capabilities: AdapterCapabilities;

	// -- Initialization --

	/** Initialize the backend (WASM init or Tauri readiness check). */
	init(): Promise<void>;

	// -- Engine state --

	/** Get a snapshot of the current engine configuration. */
	getEngineState(): Promise<EngineState>;

	/** Set the musical key (e.g. "C", "Db", "F#"). */
	setKey(key: string): Promise<void>;

	/** Set the harmony mode (e.g. "PassThrough", "DiatonicThirds"). */
	setMode(mode: string): Promise<void>;

	/** Set the scale mode (e.g. "Ionian", "Dorian", "HarmonicMinor"). */
	setScaleMode(mode: string): Promise<void>;

	/** Set the octave mode (e.g. "None", "Spread", "Mirror"). */
	setOctaveMode(mode: string): Promise<void>;

	/** Continuous octave-spread coefficient applied to Spread / Split modes.
	 *  Range [0.0, 1.0]; 0 = no displacement, 1 = full-octave (legacy)
	 *  displacement. Used by the Performance view's Spread knob for
	 *  smooth audible morphs. */
	setOctaveIntensity(amount: number): Promise<void>;

	/** Configure voice leading (enabled flag + style). */
	setVoiceLeading(enabled: boolean, style: string): Promise<void>;

	/** Configure modal interchange (enabled flag + borrowing range). */
	setInterchange(enabled: boolean, range: number): Promise<void>;

	/** Set the voice position (which output slot carries the melody). */
	setVoicePosition(position: number): Promise<void>;

	/** Set the number of output voices (1 = melody only, 2+ = melody + harmonies). */
	setVoiceCount(count: number): Promise<void>;

	/** Enable or disable auto-key detection. */
	setAutoKey(enabled: boolean): Promise<void>;

	/**
	 * Set the counterpoint species (1-4) used when the harmony mode is
	 * `StrictCounterpoint`. Values: `"Species1"`, `"Species2"`, `"Species3"`,
	 * `"Species4"`.
	 */
	setCounterpointSpecies(species: string): Promise<void>;

	/**
	 * Set the counterpoint strictness (`"Relaxed"` or `"Strict"`) applied
	 * to the counterpoint scoring weights.
	 */
	setCounterpointStrictness(strictness: string): Promise<void>;

	// -- Companion / CanonLane (#3) --

	/** Master enable for the Companion orchestrator (#91). Required for
	 *  any registered Lane (including CanonLane) to actually run. */
	companionSetEnabled(enabled: boolean): Promise<void>;

	/** Read whether the Companion is currently enabled. */
	companionIsEnabled(): Promise<boolean>;

	/** Set the Companion's global HoldMode default (#11). Lanes / voices
	 *  can still override via the existing canon / counterpoint
	 *  configure paths. JSON shape:
	 *    {"kind":"cancel"}
	 *    {"kind":"near_future","tail_beats":1.0}
	 *    {"kind":"phrase_end"}
	 *    {"kind":"forever"}
	 */
	companionSetGlobalHoldMode(holdMode: HoldMode): Promise<void>;

	/** Enable / disable the Canon voice (#3). Requires the Companion
	 *  master to be enabled too — this is the per-lane gate. */
	canonSetEnabled(enabled: boolean): Promise<void>;

	/** Set the canon delay in beats. Clamped engine-side to [0.0, 8.0]. */
	canonSetDelay(beats: number): Promise<void>;

	/** Set the canon diatonic transpose for voice 0 (backward-compat).
	 *  For multi-voice canons use canonSetVoices. Clamped to [-7, +7]. */
	canonSetTranspose(degrees: number): Promise<void>;

	/** Replace the canon voices array. Each voice has its own delay
	 *  and transpose so callers can configure multi-entry canons
	 *  (3-voice at +0/+2/+4 beats, etc). Clamped to 8 voices max. */
	canonSetVoices(
		voices: Array<{
			delay_beats: number;
			transpose_degrees: number;
			time_ratio?: number;
			harmony_mode?: string | null;
			reference_voice?: number | null;
			voice_count?: number | null;
			voice_position?: number | null;
			voice_leading_enabled?: boolean | null;
			voice_leading_style?: string | null;
			octave_mode?: string | null;
			counterpoint_species?: string | null;
			counterpoint_strictness?: string | null;
			hold_mode?: HoldMode | null;
		}>
	): Promise<void>;

	/** Generic lane-level configure for CanonLane (#11 override path).
	 *  Sends an arbitrary partial JSON state blob to the lane's
	 *  `deserialize_state`. Use for fields not covered by the typed
	 *  setters above — currently the lane-level `hold_mode` field. */
	canonConfigure(partial: Record<string, unknown>): Promise<void>;

	/** Configure the dedicated CounterpointLane. Each field is
	 *  optional — only the ones you pass are applied. */
	counterpointSetConfig(config: {
		enabled?: boolean;
		species?: string;
		transpose_degrees?: number;
		prefer_above?: boolean;
	}): Promise<void>;

	/** Generic lane-level configure for CounterpointLane (#11 override
	 *  path). Same shape as `canonConfigure`. */
	counterpointConfigure(partial: Record<string, unknown>): Promise<void>;

	/** Read the dedicated CounterpointLane's current state. */
	counterpointState(): Promise<{
		enabled: boolean;
		species: string;
		transpose_degrees: number;
		prefer_above: boolean;
	} | null>;

	/** Read the canon lane's full config snapshot. */
	canonState(): Promise<{
		enabled: boolean;
		delay_beats: number;
		transpose_degrees: number;
		voices?: Array<{
			delay_beats: number;
			transpose_degrees: number;
			time_ratio?: number;
			harmony_mode?: string | null;
			reference_voice?: number | null;
		}>;
	} | null>;

	// -- MIDI devices --

	/**
	 * Browser-only: request Web MIDI permission via a user gesture.
	 *
	 * Adapters that don't gate MIDI behind a gesture (Tauri, Plugin) return
	 * `'granted'` immediately. The browser adapter calls
	 * `navigator.requestMIDIAccess()` and resolves with the resulting state.
	 *
	 * Callers should gate device enumeration on this returning `'granted'`.
	 */
	requestMidiPermission(): Promise<MidiPermissionState>;

	/** Current MIDI permission state. `'granted'` for native paths. */
	readonly midiPermissionState: MidiPermissionState;

	/** List available MIDI input devices. */
	listMidiInputs(): Promise<MidiDevice[]>;

	/** List available MIDI output devices. */
	listMidiOutputs(): Promise<MidiDevice[]>;

	/** Re-enumerate MIDI devices (forces a fresh scan). */
	refreshMidiDevices(): Promise<void>;

	// -- Routing --

	/** Start MIDI routing from the given input to the given outputs. */
	startRouting(inputIdx: number, outputIndices: number[]): Promise<void>;

	/** Stop the currently active MIDI routing. */
	stopRouting(): Promise<void>;

	// -- Per-voice output routing --

	/**
	 * Set the output destination for a single voice by index (0..7).
	 * Each voice can go independently to the internal synth, a specific
	 * external MIDI port, nowhere (off), or fall back to the global
	 * routing mode (use_default).
	 */
	setVoiceOutput(voiceIdx: number, target: VoiceOutputTarget): Promise<void>;

	/**
	 * Get the current voice-output routing table. Array length = MAX_VOICES
	 * (8). Each entry is the destination for that voice index.
	 */
	getVoiceOutputs(): Promise<VoiceOutputTarget[]>;

	// -- Plugin host routing controls --
	getPluginInputMode(): Promise<PluginInputMode>;
	setPluginInputMode(mode: PluginInputMode): Promise<void>;
	getPluginMidiOutputMode(): Promise<PluginMidiOutputMode>;
	setPluginMidiOutputMode(mode: PluginMidiOutputMode): Promise<void>;
	getPluginSynthEnabled(): Promise<boolean>;
	setPluginSynthEnabled(enabled: boolean): Promise<void>;
	panicAllNotesOff(): Promise<void>;
	/** Subscribe to DAW/plugin parameter changes (automation, controller assignments). */
	onPluginParamsUpdate(callback: () => void): () => void;

	// -- Real-time state --

	/**
	 * Subscribe to real-time note updates.
	 * Returns an unsubscribe function.
	 */
	onNoteUpdate(callback: (state: NoteState) => void): () => void;

	/**
	 * Subscribe to raw MIDI CC events. Every Control Change message
	 * received on the active input is forwarded with its raw CC number
	 * and normalized 0..1 value. The Performance view uses this to
	 * implement MIDI Learn — it maps CC numbers to software-knob
	 * indices via a user-configurable table persisted in localStorage.
	 * Browser/wasm/plugin platforms that don't deliver raw MIDI CC
	 * may return a no-op.
	 *
	 * Returns an unsubscribe function.
	 */
	onKnobCcRaw(callback: (cc: number, value: number) => void): () => void;

	// -- Virtual Input (keyboard) --

	/** Inject a Note On event directly (for virtual inputs like computer keyboard). */
	injectNoteOn(note: number, velocity?: number): Promise<number[]>;

	/** Inject a Note Off event directly (for virtual inputs). */
	injectNoteOff(note: number): Promise<number[]>;

	// -- Presets --

	/** List all available presets (builtins + custom). */
	listPresets(): Promise<Preset[]>;

	/** Load a preset by name and apply it to the engine. */
	loadPreset(name: string): Promise<void>;

	/** Save the current engine config as a custom preset. */
	savePreset(name: string): Promise<void>;

	/** Delete a custom preset by name. */
	deletePreset(name: string): Promise<void>;

	// -- Guitar input --

	/** List available audio input devices (via cpal on desktop). */
	listAudioDevices(): Promise<string[]>;

	/** Set the guitar audio input device and channel. */
	setGuitarDevice(deviceName: string, channel: number): Promise<void>;

	/** Set the guitar DSP pipeline configuration. */
	setGuitarConfig(config: GuitarConfig): Promise<void>;

	/** Read the current calibration status (whether a profile exists on
	 *  disk, where, and per-string sample counts). Stubbed on adapters
	 *  whose `capabilities.calibrationFlow` is false. */
	getCalibrationStatus(): Promise<CalibrationStatus>;

	/** Force-reload the calibration profile from disk into AppState. */
	loadCalibrationProfile(): Promise<CalibrationStatus>;

	/** Save a JSON-serialized calibration profile to disk. */
	saveCalibrationProfile(profileJson: string): Promise<CalibrationStatus>;

	/** Delete the calibration profile from disk and reset to defaults.
	 *  Gives users a "Reset to Default" affordance — useful when a
	 *  bad calibration sweep poisons the file. */
	deleteCalibrationProfile(): Promise<CalibrationStatus>;

	/** Get the engine's current port-map: for each result-index `i`
	 *  (0 = the user's input/melody, 1..N = harmony voices), the
	 *  arrangement slot the engine will route that voice through.
	 *  Empty when the engine has not processed any notes yet; UI should
	 *  fall back to a config-derived mapping in that case. Used by the
	 *  Voice Generation Chain to reflect the engine's ACTUAL routing
	 *  for Species 2-4, drop voicings, and inversions rather than
	 *  assuming `voicePosition` directly. */
	getLastPortMap(): Promise<number[]>;

	// -- Detune --

	/** Set global detune in cents (sends pitch bend to all outputs). */
	setDetune(cents: number): void;

	/** Get the current detune value in cents. */
	getDetune(): number;

	// -- Transport (sample-accurate clock) --

	/** Get a snapshot of the current transport state. */
	getTransportState(): Promise<TransportState>;

	/** Start the transport (resume from current position). */
	transportPlay(): Promise<void>;

	/** Stop the transport (freeze at current position). */
	transportStop(): Promise<void>;

	/** Reset sample position to 0. */
	transportReset(): Promise<void>;

	/** Set the tempo in BPM (clamped to [20, 400] on the backend). */
	setBpm(bpm: number): Promise<void>;

	/** Set the time signature (beats per bar × beat unit). */
	setTimeSignature(beatsPerBar: number, beatUnit: number): Promise<void>;

	/** Toggle the audible metronome click. Off by default. */
	setMetronomeEnabled(enabled: boolean): Promise<void>;

	// -- Built-in synth (Tier 1 audio output) --

	getSynthState(): Promise<SynthState>;
	setSynthEnabled(enabled: boolean): Promise<void>;
	setSynthWaveform(value: number): Promise<void>;
	setSynthAttackMs(ms: number): Promise<void>;
	setSynthDecayMs(ms: number): Promise<void>;
	setSynthSustain(level: number): Promise<void>;
	setSynthReleaseMs(ms: number): Promise<void>;
	setSynthCutoffHz(hz: number): Promise<void>;
	setSynthResonance(value: number): Promise<void>;
	setSynthMasterGain(value: number): Promise<void>;
	setSynthMixGain(group: number, value: number): Promise<void>;

	// -- Built-in FX (reverb) --

	getReverbState(): Promise<ReverbState>;
	setReverbEnabled(enabled: boolean): Promise<void>;
	setReverbMix(value: number): Promise<void>;
	setReverbRoomSize(value: number): Promise<void>;
	setReverbDamping(value: number): Promise<void>;

	getDelayState(): Promise<DelayState>;
	setDelayEnabled(enabled: boolean): Promise<void>;
	setDelayMix(value: number): Promise<void>;
	setDelayTimeMs(ms: number): Promise<void>;
	setDelayFeedback(value: number): Promise<void>;
	setDelaySyncEnabled(enabled: boolean): Promise<void>;
	setDelaySubdivision(subdivision: DelaySubdivision): Promise<void>;

	// -- Audio chain topology --

	listChainBlocks(): Promise<ChainBlock[]>;
	removeChainBlock(index: number): Promise<void>;
	clearChain(): Promise<void>;

	// -- CLAP plugin host --

	listClapPlugins(): Promise<ClapPluginDescriptor[]>;
	addClapPluginToChain(path: string): Promise<AddedPlugin>;
	openPluginGui(pluginId: number): Promise<void>;
	getPluginGuiSize(pluginId: number): Promise<{ width: number; height: number } | null>;
	openPluginGuiEmbedded(
		pluginId: number,
		x: number,
		y: number,
		width: number,
		height: number
	): Promise<void>;
	setPluginGuiFrame(
		pluginId: number,
		x: number,
		y: number,
		width: number,
		height: number
	): Promise<void>;
	closePluginGui(pluginId: number): Promise<void>;
	removePlugin(pluginId: number): Promise<void>;

	// -- Lifecycle --

	/**
	 * Tear down any background loops, event listeners, or audio contexts
	 * owned by this adapter. Called from the root layout `onDestroy` hook
	 * so hot-reload and navigation don't leak requestAnimationFrame loops.
	 */
	destroy?(): void;
}

text:
//! Harmony configuration types.
//!
//! This module defines the enums used to configure the harmony engine:
//! musical keys, harmony modes, octave modes, scale modes, and routing modes.

use serde::{Deserialize, Serialize};

/// MIDI routing mode for harmony voice output.
///
/// Controls how harmony voices are distributed to MIDI destinations.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RoutingMode {
    /// Channel-based (MPE): all voices on one output, separated by MIDI channel.
    /// Ch 1 = master, Ch 2 = melody, Ch 3-7 = harmony voices.
    /// Default — works in VST/AU plugins and requires only one MIDI connection.
    #[default]
    ChannelBased,
    /// Port-based: each voice goes to a separate MIDI output port.
    /// Requires multiple IAC buses or MIDI outputs. Legacy mode for
    /// multi-bus DAW routing.
    PortBased,
}

/// Musical keys (C through B, 12 options).
///
/// Represents the tonic of a scale. Used with [`ScaleMode`] to define
/// the complete scale for harmony generation.
///
/// Each key corresponds to a pitch class (0-11) where C=0, Db=1, ..., B=11.
///
/// # Example
///
/// ```
/// use contrapunk::harmony::Key;
///
/// let key = Key::C;
/// assert_eq!(key.semitones_from_c(), 0);
///
/// let key = Key::G;
/// assert_eq!(key.semitones_from_c(), 7);
/// ```
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Key {
    C,
    Db,
    D,
    Eb,
    E,
    F,
    Gb,
    G,
    Ab,
    A,
    Bb,
    B,
}

impl Key {
    /// Returns semitones from C (0-11).
    ///
    /// This value is used as the tonic pitch class when constructing scales.
    pub fn semitones_from_c(&self) -> u8 {
        match self {
            Key::C => 0,
            Key::Db => 1,
            Key::D => 2,
            Key::Eb => 3,
            Key::E => 4,
            Key::F => 5,
            Key::Gb => 6,
            Key::G => 7,
            Key::Ab => 8,
            Key::A => 9,
            Key::Bb => 10,
            Key::B => 11,
        }
    }

    /// Returns all keys in order for menu display.
    ///
    /// # Example
    ///
    /// ```
    /// use contrapunk::harmony::Key;
    ///
    /// let keys = Key::all();
    /// assert_eq!(keys.len(), 12);
    /// assert_eq!(keys[0], Key::C);
    /// ```
    pub fn all() -> &'static [Key] {
        &[
            Key::C,
            Key::Db,
            Key::D,
            Key::Eb,
            Key::E,
            Key::F,
            Key::Gb,
            Key::G,
            Key::Ab,
            Key::A,
            Key::Bb,
            Key::B,
        ]
    }
}

impl std::fmt::Display for Key {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{:?}", self)
    }
}

/// Octave placement modes for harmony voices.
///
/// Controls how harmony notes are shifted in octave after generation.
/// Applied as post-processing after the harmony algorithm runs.
///
/// # Example
///
/// ```
/// use contrapunk::harmony::OctaveMode;
///
/// let mode = OctaveMode::default();
/// assert_eq!(mode, OctaveMode::None);
///
/// for mode in OctaveMode::all() {
///     println!("{}: {}", mode, mode.description());
/// }
/// ```
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum OctaveMode {
    /// No octave modification - harmonies stay at their generated pitch.
    #[default]
    None,
    /// Spread voices across octaves - each successive voice is +1 octave higher.
    Spread,
    /// Bass/Treble split - harmonies below melody go down an octave, above go up.
    BassTrebleSplit,
    /// Mirror - duplicate each harmony note in +1 and -1 octaves (tripling harmony notes).
    Mirror,
}

impl OctaveMode {
    /// Returns all octave modes for menu display.
    pub fn all() -> &'static [OctaveMode] {
        &[
            OctaveMode::None,
            OctaveMode::Spread,
            OctaveMode::BassTrebleSplit,
            OctaveMode::Mirror,
        ]
    }

    /// Returns description for menu display.
    pub fn description(&self) -> &'static str {
        match self {
            OctaveMode::None => "None (default pitch)",
            OctaveMode::Spread => "Spread (+1 octave per voice)",
            OctaveMode::BassTrebleSplit => "Bass/Treble split",
            OctaveMode::Mirror => "Mirror (±1 octave)",
        }
    }
}

impl std::fmt::Display for OctaveMode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.description())
    }
}

/// Scale family grouping for UI display.
///
/// Organizes the 57 scale modes into 10 logical families for easier navigation.
/// Each family contains related modes derived from the same parent scale
/// or sharing a common construction principle.
///
/// # Families
///
/// - **Diatonic**: The 7 modes of the major scale (Ionian, Dorian, etc.)
/// - **HarmonicMinor**: The 7 modes of the harmonic minor scale
/// - **MelodicMinor**: The 7 modes of the melodic minor (ascending) scale
/// - **HarmonicMajor**: The 7 modes of the harmonic major scale
/// - **DoubleHarmonic**: The 7 modes of the double harmonic scale
/// - **Pentatonic**: 5-note scales (major/minor pentatonic, Japanese, Balinese)
/// - **Blues**: Blues scales and bebop dominant (6-8 notes)
/// - **Symmetric**: Scales with transpositional symmetry (whole tone, diminished, augmented)
/// - **World**: Scales from diverse traditions (Persian, Hungarian Major, Enigmatic, Neapolitan)
/// - **BarryHarris**: 8-note bebop scales with added diminished passing tones
///
/// # Example
///
/// ```
/// use contrapunk::harmony::{ScaleFamily, ScaleMode};
///
/// let dorian = ScaleMode::Dorian;
/// assert_eq!(dorian.family(), ScaleFamily::Diatonic);
///
/// let phrygian_dom = ScaleMode::PhrygianDominant;
/// assert_eq!(phrygian_dom.family(), ScaleFamily::HarmonicMinor);
/// ```
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ScaleFamily {
    /// Diatonic modes (Ionian through Locrian) - the 7 modes of the major scale.
    #[serde(alias = "church")]
    Diatonic,
    /// Harmonic minor modes - characterized by the augmented 2nd interval.
    HarmonicMinor,
    /// Melodic minor modes - also known as jazz minor modes.
    MelodicMinor,
    /// Harmonic major modes - major scale with lowered 6th and its rotations.
    HarmonicMajor,
    /// Double harmonic modes - two augmented 2nd intervals and rotations.
    DoubleHarmonic,
    /// Pentatonic scales - 5-note scales from various traditions.
    Pentatonic,
    /// Blues and bebop scales - 6 or 8 note scales with chromatic additions.
    Blues,
    /// Symmetric scales - scales with transpositional symmetry.
    Symmetric,
    /// World scales - scales from diverse musical traditions.
    #[serde(alias = "exotic")]
    World,
    /// Barry Harris 6th diminished scales - 8-note bebop scales.
    BarryHarris,
}

impl ScaleFamily {
    /// Returns all scale families.
    pub fn all() -> &'static [ScaleFamily] {
        &[
            ScaleFamily::Diatonic,
            ScaleFamily::HarmonicMinor,
            ScaleFamily::MelodicMinor,
            ScaleFamily::HarmonicMajor,
            ScaleFamily::DoubleHarmonic,
            ScaleFamily::Pentatonic,
            ScaleFamily::Blues,
            ScaleFamily::Symmetric,
            ScaleFamily::World,
            ScaleFamily::BarryHarris,
        ]
    }
}

impl std::fmt::Display for ScaleFamily {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ScaleFamily::Diatonic => write!(f, "Diatonic Modes"),
            ScaleFamily::HarmonicMinor => write!(f, "Harmonic Minor"),
            ScaleFamily::MelodicMinor => write!(f, "Melodic Minor"),
            ScaleFamily::HarmonicMajor => write!(f, "Harmonic Major"),
            ScaleFamily::DoubleHarmonic => write!(f, "Double Harmonic"),
            ScaleFamily::Pentatonic => write!(f, "Pentatonic"),
            ScaleFamily::Blues => write!(f, "Blues & Bebop"),
            ScaleFamily::Symmetric => write!(f, "Symmetric"),
            ScaleFamily::World => write!(f, "World Scales"),
            ScaleFamily::BarryHarris => write!(f, "Barry Harris"),
        }
    }
}

/// Scale modes (57 variants grouped by family).
///
/// Defines the interval pattern for a scale. Combined with a [`Key`] (tonic),
/// this determines which notes belong to the scale and how diatonic
/// transposition works.
///
/// Scale cardinalities: pentatonic (5), hexatonic/blues (6), heptatonic (7),
/// octatonic/bebop (8). Barry Harris and bebop scales have 8 notes.
///
/// # Families (10)
///
/// - **Diatonic (7)**: Ionian, Dorian, Phrygian, Lydian, Mixolydian, Aeolian, Locrian
/// - **Harmonic Minor (7)**: HarmonicMinor, LocrianNat6, IonianAug, DorianSharp4,
///   PhrygianDominant, LydianSharp2, SuperLocrianDim
/// - **Melodic Minor (7)**: MelodicMinor, DorianFlat2, LydianAug, LydianDominant,
///   MixolydianFlat6, LocrianNat2, SuperLocrian
/// - **Harmonic Major (7)**: HarmonicMajor through LocrianDoubleFlat7
/// - **Double Harmonic (7)**: DoubleHarmonic, LydianSharp2Sharp6, Ultraphrygian,
///   HungarianMinor, Oriental, IonianSharp2Sharp5, LocrianDoubleFlat3DoubleFlat7
/// - **Pentatonic (8)**: MajorPentatonic, MinorPentatonic, Hirajoshi, InSen, Iwato,
///   Yo, Kumoi, Pelog
/// - **Blues & Bebop (3)**: MinorBlues, MajorBlues, BebopDominant
/// - **Symmetric (4)**: WholeTone, DiminishedWholeHalf, DiminishedHalfWhole, AugmentedHex
/// - **World (5)**: Enigmatic, NeapolitanMinor, NeapolitanMajor, Persian, HungarianMajor
/// - **Barry Harris (2)**: BHMajor6thDim, BHMinor6thDim
///
/// Scales sourced from langoy.net/skala (mathematical interval data).
///
/// # Example
///
/// ```
/// use contrapunk::harmony::ScaleMode;
///
/// // Get intervals for C Dorian: C D Eb F G A Bb
/// let dorian = ScaleMode::Dorian;
/// let intervals = dorian.intervals();
/// assert_eq!(intervals, &[0, 2, 3, 5, 7, 9, 10]);
///
/// // Barry Harris scales have 8 notes
/// let bh = ScaleMode::BHMajor6thDim;
/// assert_eq!(bh.intervals().len(), 8);
///
/// // Pentatonic scales have 5 notes
/// let pent = ScaleMode::MinorPentatonic;
/// assert_eq!(pent.intervals().len(), 5);
/// ```
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ScaleMode {
    // Diatonic modes (7)
    /// Ionian mode (major scale): W-W-H-W-W-W-H
    Ionian,
    /// Dorian mode: W-H-W-W-W-H-W (minor with raised 6th)
    Dorian,
    /// Phrygian mode: H-W-W-W-H-W-W (minor with lowered 2nd)
    Phrygian,
    /// Lydian mode: W-W-W-H-W-W-H (major with raised 4th)
    Lydian,
    /// Mixolydian mode: W-W-H-W-W-H-W (major with lowered 7th)
    Mixolydian,
    /// Aeolian mode (natural minor): W-H-W-W-H-W-W
    Aeolian,
    /// Locrian mode: H-W-W-H-W-W-W (diminished tonic)
    Locrian,

    // Harmonic minor modes (7)
    /// Harmonic minor: natural minor with raised 7th
    HarmonicMinor,
    /// Locrian natural 6: Locrian with natural 6th
    LocrianNat6,
    /// Ionian augmented: major with raised 5th
    IonianAug,
    /// Dorian #4: Dorian with raised 4th
    DorianSharp4,
    /// Phrygian dominant: Phrygian with raised 3rd (Spanish scale)
    PhrygianDominant,
    /// Lydian #2: Lydian with raised 2nd
    LydianSharp2,
    /// Super Locrian diminished: altered scale variant
    SuperLocrianDim,

    // Melodic minor modes (7)
    /// Melodic minor (ascending): minor with raised 6th and 7th
    MelodicMinor,
    /// Dorian b2: Dorian with lowered 2nd
    DorianFlat2,
    /// Lydian augmented: Lydian with raised 5th
    LydianAug,
    /// Lydian dominant: Lydian with lowered 7th
    LydianDominant,
    /// Mixolydian b6: Mixolydian with lowered 6th
    MixolydianFlat6,
    /// Locrian natural 2: Locrian with natural 2nd
    LocrianNat2,
    /// Super Locrian (altered scale): all tensions altered
    SuperLocrian,

    // Harmonic major modes (7) — major scale with lowered 6th
    /// Harmonic major: major scale with b6 (7 notes)
    HarmonicMajor,
    /// Dorian b5: mode 2 of harmonic major (7 notes)
    DorianFlat5,
    /// Phrygian b4: mode 3 of harmonic major (7 notes)
    PhrygianFlat4,
    /// Lydian b3 (Lydian diminished): mode 4 of harmonic major (7 notes)
    LydianFlat3,
    /// Mixolydian b2: mode 5 of harmonic major (7 notes)
    MixolydianFlat2,
    /// Lydian augmented #2: mode 6 of harmonic major (7 notes)
    LydianAugSharp2,
    /// Locrian bb7: mode 7 of harmonic major (7 notes)
    LocrianDoubleFlat7,

    // Double harmonic modes (7) — two augmented 2nd intervals
    /// Double harmonic: mode 1, two augmented 2nd intervals (7 notes)
    DoubleHarmonic,
    /// Lydian #2 #6: mode 2 of double harmonic (7 notes)
    LydianSharp2Sharp6,
    /// Ultraphrygian: mode 3 of double harmonic (7 notes)
    Ultraphrygian,
    /// Hungarian minor: mode 4 of double harmonic, harmonic minor with #4 (7 notes)
    HungarianMinor,
    /// Oriental: mode 5 of double harmonic (7 notes)
    Oriental,
    /// Ionian #2 #5: mode 6 of double harmonic (7 notes)
    IonianSharp2Sharp5,
    /// Locrian bb3 bb7: mode 7 of double harmonic (7 notes)
    LocrianDoubleFlat3DoubleFlat7,

    // Pentatonic (8) — 5-note scales
    /// Major pentatonic: the most common 5-note scale (5 notes)
    MajorPentatonic,
    /// Minor pentatonic: the most used guitar scale (5 notes)
    MinorPentatonic,
    /// Hirajoshi: Japanese pentatonic (5 notes)
    Hirajoshi,
    /// In Sen: Japanese pentatonic, mode 4 of Hirajoshi (5 notes)
    InSen,
    /// Iwato: Japanese pentatonic, mode 2 of Hirajoshi (5 notes)
    Iwato,
    /// Yo: mode 4 of major pentatonic (5 notes)
    Yo,
    /// Kumoi: Japanese pentatonic (5 notes)
    Kumoi,
    /// Pelog: Balinese/Javanese pentatonic (5 notes)
    Pelog,

    // Blues & Bebop (3)
    /// Minor blues: minor pentatonic + b5 (6 notes)
    MinorBlues,
    /// Major blues: major pentatonic + #2 (6 notes)
    MajorBlues,
    /// Bebop dominant: dominant 7th + natural 7th passing tone (8 notes)
    BebopDominant,

    // Symmetric (4) — scales with transpositional symmetry
    /// Whole tone: 6 equally-spaced notes (6 notes, symmetry order 6)
    WholeTone,
    /// Diminished whole-half: alternating W-H (8 notes, symmetry order 4)
    DiminishedWholeHalf,
    /// Diminished half-whole: alternating H-W (8 notes, symmetry order 4)
    DiminishedHalfWhole,
    /// Augmented hexatonic: alternating m3-H (6 notes, symmetry order 3)
    AugmentedHex,

    // World scales (5) — diverse musical traditions
    /// Enigmatic: synthetic scale with unusual intervals (7 notes)
    Enigmatic,
    /// Neapolitan minor: harmonic minor with lowered 2nd (7 notes)
    NeapolitanMinor,
    /// Neapolitan major: major with lowered 2nd (7 notes)
    NeapolitanMajor,
    /// Persian: similar to double harmonic but with b5 (7 notes)
    Persian,
    /// Hungarian major: Lydian dominant with #2 (7 notes)
    HungarianMajor,

    // Barry Harris (2) — 8-note bebop scales
    /// Barry Harris major 6th diminished: 8-note bebop major scale
    BHMajor6thDim,
    /// Barry Harris minor 6th diminished: 8-note bebop minor scale
    BHMinor6thDim,
}

impl ScaleMode {
    /// Returns semitone offsets from tonic for each scale degree.
    ///
    /// Returns a static slice -- no heap allocation. Scale cardinalities:
    /// pentatonic (5), hexatonic (6), heptatonic (7), octatonic (8).
    ///
    /// # Example
    ///
    /// ```
    /// use contrapunk::harmony::ScaleMode;
    ///
    /// // C Major intervals: C(0) D(2) E(4) F(5) G(7) A(9) B(11)
    /// assert_eq!(ScaleMode::Ionian.intervals(), &[0, 2, 4, 5, 7, 9, 11]);
    ///
    /// // C Dorian intervals: C(0) D(2) Eb(3) F(5) G(7) A(9) Bb(10)
    /// assert_eq!(ScaleMode::Dorian.intervals(), &[0, 2, 3, 5, 7, 9, 10]);
    /// ```
    pub fn intervals(&self) -> &'static [u8] {
        match self {
            // Diatonic modes (7 notes)
            ScaleMode::Ionian => &[0, 2, 4, 5, 7, 9, 11],
            ScaleMode::Dorian => &[0, 2, 3, 5, 7, 9, 10],
            ScaleMode::Phrygian => &[0, 1, 3, 5, 7, 8, 10],
            ScaleMode::Lydian => &[0, 2, 4, 6, 7, 9, 11],
            ScaleMode::Mixolydian => &[0, 2, 4, 5, 7, 9, 10],
            ScaleMode::Aeolian => &[0, 2, 3, 5, 7, 8, 10],
            ScaleMode::Locrian => &[0, 1, 3, 5, 6, 8, 10],
            // Harmonic minor modes (7 notes)
            ScaleMode::HarmonicMinor => &[0, 2, 3, 5, 7, 8, 11],
            ScaleMode::LocrianNat6 => &[0, 1, 3, 5, 6, 9, 10],
            ScaleMode::IonianAug => &[0, 2, 4, 5, 8, 9, 11],
            ScaleMode::DorianSharp4 => &[0, 2, 3, 6, 7, 9, 10],
            ScaleMode::PhrygianDominant => &[0, 1, 4, 5, 7, 8, 10],
            ScaleMode::LydianSharp2 => &[0, 3, 4, 6, 7, 9, 11],
            ScaleMode::SuperLocrianDim => &[0, 1, 3, 4, 6, 8, 9],
            // Melodic minor modes (7 notes)
            ScaleMode::MelodicMinor => &[0, 2, 3, 5, 7, 9, 11],
            ScaleMode::DorianFlat2 => &[0, 1, 3, 5, 7, 9, 10],
            ScaleMode::LydianAug => &[0, 2, 4, 6, 8, 9, 11],
            ScaleMode::LydianDominant => &[0, 2, 4, 6, 7, 9, 10],
            ScaleMode::MixolydianFlat6 => &[0, 2, 4, 5, 7, 8, 10],
            ScaleMode::LocrianNat2 => &[0, 2, 3, 5, 6, 8, 10],
            ScaleMode::SuperLocrian => &[0, 1, 3, 4, 6, 8, 10],
            // Harmonic major modes (7 notes)
            ScaleMode::HarmonicMajor => &[0, 2, 4, 5, 7, 8, 11],
            ScaleMode::DorianFlat5 => &[0, 2, 3, 5, 6, 9, 10],
            ScaleMode::PhrygianFlat4 => &[0, 1, 3, 4, 7, 9, 10],
            ScaleMode::LydianFlat3 => &[0, 2, 3, 6, 7, 9, 11],
            ScaleMode::MixolydianFlat2 => &[0, 1, 4, 5, 7, 9, 10],
            ScaleMode::LydianAugSharp2 => &[0, 3, 4, 6, 8, 9, 11],
            ScaleMode::LocrianDoubleFlat7 => &[0, 1, 3, 5, 6, 8, 9],
            // Double harmonic modes (7 notes)
            ScaleMode::DoubleHarmonic => &[0, 1, 4, 5, 7, 8, 11],
            ScaleMode::LydianSharp2Sharp6 => &[0, 3, 4, 6, 7, 10, 11],
            ScaleMode::Ultraphrygian => &[0, 1, 3, 4, 7, 8, 9],
            ScaleMode::HungarianMinor => &[0, 2, 3, 6, 7, 8, 11],
            ScaleMode::Oriental => &[0, 1, 4, 5, 6, 9, 10],
            ScaleMode::IonianSharp2Sharp5 => &[0, 3, 4, 5, 8, 9, 11],
            ScaleMode::LocrianDoubleFlat3DoubleFlat7 => &[0, 1, 2, 5, 6, 8, 9],
            // Pentatonic (5 notes)
            ScaleMode::MajorPentatonic => &[0, 2, 4, 7, 9],
            ScaleMode::MinorPentatonic => &[0, 3, 5, 7, 10],
            ScaleMode::Hirajoshi => &[0, 2, 3, 7, 8],
            ScaleMode::InSen => &[0, 1, 5, 7, 8],
            ScaleMode::Iwato => &[0, 1, 5, 6, 10],
            ScaleMode::Yo => &[0, 2, 5, 7, 9],
            ScaleMode::Kumoi => &[0, 2, 3, 7, 9],
            ScaleMode::Pelog => &[0, 1, 3, 7, 8],
            // Blues & Bebop
            ScaleMode::MinorBlues => &[0, 3, 5, 6, 7, 10],
            ScaleMode::MajorBlues => &[0, 2, 3, 4, 7, 9],
            ScaleMode::BebopDominant => &[0, 2, 4, 5, 7, 9, 10, 11],
            // Symmetric
            ScaleMode::WholeTone => &[0, 2, 4, 6, 8, 10],
            ScaleMode::DiminishedWholeHalf => &[0, 2, 3, 5, 6, 8, 9, 11],
            ScaleMode::DiminishedHalfWhole => &[0, 1, 3, 4, 6, 7, 9, 10],
            ScaleMode::AugmentedHex => &[0, 3, 4, 7, 8, 11],
            // World scales (7 notes)
            ScaleMode::Enigmatic => &[0, 1, 4, 6, 8, 10, 11],
            ScaleMode::NeapolitanMinor => &[0, 1, 3, 5, 7, 8, 11],
            ScaleMode::NeapolitanMajor => &[0, 1, 3, 5, 7, 9, 11],
            ScaleMode::Persian => &[0, 1, 4, 5, 6, 8, 11],
            ScaleMode::HungarianMajor => &[0, 3, 4, 6, 7, 9, 10],
            // Barry Harris 6th Diminished (8 notes)
            ScaleMode::BHMajor6thDim => &[0, 2, 4, 5, 7, 8, 9, 11],
            ScaleMode::BHMinor6thDim => &[0, 2, 3, 5, 7, 8, 9, 11],
        }
    }

    /// Returns the scale family for this mode.
    ///
    /// Used for grouping modes in the UI and determining related scales.
    pub fn family(&self) -> ScaleFamily {
        match self {
            ScaleMode::Ionian
            | ScaleMode::Dorian
            | ScaleMode::Phrygian
            | ScaleMode::Lydian
            | ScaleMode::Mixolydian
            | ScaleMode::Aeolian
            | ScaleMode::Locrian => ScaleFamily::Diatonic,

            ScaleMode::HarmonicMinor
            | ScaleMode::LocrianNat6
            | ScaleMode::IonianAug
            | ScaleMode::DorianSharp4
            | ScaleMode::PhrygianDominant
            | ScaleMode::LydianSharp2
            | ScaleMode::SuperLocrianDim => ScaleFamily::HarmonicMinor,

            ScaleMode::MelodicMinor
            | ScaleMode::DorianFlat2
            | ScaleMode::LydianAug
            | ScaleMode::LydianDominant
            | ScaleMode::MixolydianFlat6
            | ScaleMode::LocrianNat2
            | ScaleMode::SuperLocrian => ScaleFamily::MelodicMinor,

            ScaleMode::HarmonicMajor
            | ScaleMode::DorianFlat5
            | ScaleMode::PhrygianFlat4
            | ScaleMode::LydianFlat3
            | ScaleMode::MixolydianFlat2
            | ScaleMode::LydianAugSharp2
            | ScaleMode::LocrianDoubleFlat7 => ScaleFamily::HarmonicMajor,

            ScaleMode::DoubleHarmonic
            | ScaleMode::LydianSharp2Sharp6
            | ScaleMode::Ultraphrygian
            | ScaleMode::HungarianMinor
            | ScaleMode::Oriental
            | ScaleMode::IonianSharp2Sharp5
            | ScaleMode::LocrianDoubleFlat3DoubleFlat7 => ScaleFamily::DoubleHarmonic,

            ScaleMode::MajorPentatonic
            | ScaleMode::MinorPentatonic
            | ScaleMode::Hirajoshi
            | ScaleMode::InSen
            | ScaleMode::Iwato
            | ScaleMode::Yo
            | ScaleMode::Kumoi
            | ScaleMode::Pelog => ScaleFamily::Pentatonic,

            ScaleMode::MinorBlues | ScaleMode::MajorBlues | ScaleMode::BebopDominant => {
                ScaleFamily::Blues
            }

            ScaleMode::WholeTone
            | ScaleMode::DiminishedWholeHalf
            | ScaleMode::DiminishedHalfWhole
            | ScaleMode::AugmentedHex => ScaleFamily::Symmetric,

            ScaleMode::Enigmatic
            | ScaleMode::NeapolitanMinor
            | ScaleMode::NeapolitanMajor
            | ScaleMode::Persian
            | ScaleMode::HungarianMajor => ScaleFamily::World,

            ScaleMode::BHMajor6thDim | ScaleMode::BHMinor6thDim => ScaleFamily::BarryHarris,
        }
    }

    /// Returns all scale modes for menu display.
    ///
    /// Modes are ordered by family: Diatonic, Harmonic Minor, Melodic Minor,
    /// Harmonic Major, Double Harmonic, Pentatonic, Blues, Symmetric, World,
    /// Barry Harris. Total: 57 scales.
    pub fn all() -> &'static [ScaleMode] {
        &[
            // Diatonic (7)
            ScaleMode::Ionian,
            ScaleMode::Dorian,
            ScaleMode::Phrygian,
            ScaleMode::Lydian,
            ScaleMode::Mixolydian,
            ScaleMode::Aeolian,
            ScaleMode::Locrian,
            // Harmonic Minor (7)
            ScaleMode::HarmonicMinor,
            ScaleMode::LocrianNat6,
            ScaleMode::IonianAug,
            ScaleMode::DorianSharp4,
            ScaleMode::PhrygianDominant,
            ScaleMode::LydianSharp2,
            ScaleMode::SuperLocrianDim,
            // Melodic Minor (7)
            ScaleMode::MelodicMinor,
            ScaleMode::DorianFlat2,
            ScaleMode::LydianAug,
            ScaleMode::LydianDominant,
            ScaleMode::MixolydianFlat6,
            ScaleMode::LocrianNat2,
            ScaleMode::SuperLocrian,
            // Harmonic Major (7)
            ScaleMode::HarmonicMajor,
            ScaleMode::DorianFlat5,
            ScaleMode::PhrygianFlat4,
            ScaleMode::LydianFlat3,
            ScaleMode::MixolydianFlat2,
            ScaleMode::LydianAugSharp2,
            ScaleMode::LocrianDoubleFlat7,
            // Double Harmonic (7)
            ScaleMode::DoubleHarmonic,
            ScaleMode::LydianSharp2Sharp6,
            ScaleMode::Ultraphrygian,
            ScaleMode::HungarianMinor,
            ScaleMode::Oriental,
            ScaleMode::IonianSharp2Sharp5,
            ScaleMode::LocrianDoubleFlat3DoubleFlat7,
            // Pentatonic (8)
            ScaleMode::MajorPentatonic,
            ScaleMode::MinorPentatonic,
            ScaleMode::Hirajoshi,
            ScaleMode::InSen,
            ScaleMode::Iwato,
            ScaleMode::Yo,
            ScaleMode::Kumoi,
            ScaleMode::Pelog,
            // Blues & Bebop (3)
            ScaleMode::MinorBlues,
            ScaleMode::MajorBlues,
            ScaleMode::BebopDominant,
            // Symmetric (4)
            ScaleMode::WholeTone,
            ScaleMode::DiminishedWholeHalf,
            ScaleMode::DiminishedHalfWhole,
            ScaleMode::AugmentedHex,
            // World (5)
            ScaleMode::Enigmatic,
            ScaleMode::NeapolitanMinor,
            ScaleMode::NeapolitanMajor,
            ScaleMode::Persian,
            ScaleMode::HungarianMajor,
            // Barry Harris (2)
            ScaleMode::BHMajor6thDim,
            ScaleMode::BHMinor6thDim,
        ]
    }

    /// Returns all scale modes in a given family.
    ///
    /// # Example
    ///
    /// ```
    /// use contrapunk::harmony::{ScaleFamily, ScaleMode};
    ///
    /// let church_modes = ScaleMode::all_in_family(ScaleFamily::Diatonic);
    /// assert_eq!(church_modes.len(), 7);
    /// assert!(church_modes.contains(&ScaleMode::Dorian));
    /// ```
    pub fn all_in_family(family: ScaleFamily) -> Vec<ScaleMode> {
        ScaleMode::all()
            .iter()
            .filter(|m| m.family() == family)
            .copied()
            .collect()
    }
}

impl Default for ScaleMode {
    fn default() -> Self {
        ScaleMode::Ionian
    }
}

